import type { ElementType, HTMLAttributes, ReactNode } from "react";
import { cx } from "../utils/cx";
import { Surface, type SurfaceProps } from "./surface";

/** Package/plan cards side by side (a <ul>). */
export function PricingGrid({ className, ...rest }: HTMLAttributes<HTMLUListElement>) {
  return <ul {...rest} className={cx("hm-pricing-grid", className)} />;
}

export type PricingCardProps = Omit<SurfaceProps, "selected"> & {
  /** The recommended package: a thin iridescent edge and an optional label. */
  featured?: boolean;
  /** Label shown on a featured card ("Most chosen"). */
  featuredLabel?: ReactNode;
  /** The plan the viewer is on: a brighter hairline. */
  current?: boolean;
};

/**
 * A package or plan. Outlined by default; featured cards get the iridescent edge rather than a fill, so the grid keeps
 * one material.
 */
export function PricingCard({
  featured,
  featuredLabel,
  current,
  variant = "outlined",
  as = "li",
  padding = "lg",
  className,
  children,
  ...rest
}: PricingCardProps) {
  return (
    <Surface
      {...rest}
      as={as}
      variant={variant}
      padding={padding}
      selected={featured}
      lit={featured || rest.lit}
      className={cx("hm-pricing-card", className)}
      data-current={current ? "" : undefined}
    >
      {featured && featuredLabel ? <span className="hm-pricing-flag">{featuredLabel}</span> : null}
      {children}
    </Surface>
  );
}

export function PricingName({
  as: As = "h2",
  className,
  ...rest
}: HTMLAttributes<HTMLHeadingElement> & { as?: ElementType }) {
  return <As {...rest} className={cx("hm-pricing-name", className)} />;
}

export function PricingTagline({ className, ...rest }: HTMLAttributes<HTMLParagraphElement>) {
  return <p {...rest} className={cx("hm-pricing-tagline", className)} />;
}

export type PricingPriceProps = HTMLAttributes<HTMLParagraphElement> & {
  /** "per session", "/ month". */
  period?: ReactNode;
};

export function PricingPrice({ period, className, children, ...rest }: PricingPriceProps) {
  return (
    <p {...rest} className={cx("hm-pricing-price", className)}>
      {children}
      {period ? <small>{period}</small> : null}
    </p>
  );
}

/** What is included, as label / value rows on hairlines. */
export function PricingFeatures({ className, ...rest }: HTMLAttributes<HTMLUListElement>) {
  return <ul {...rest} className={cx("hm-pricing-features", className)} />;
}

export function PricingFeature({
  value,
  className,
  children,
  ...rest
}: HTMLAttributes<HTMLLIElement> & { value?: ReactNode }) {
  return (
    <li {...rest} className={cx("hm-pricing-feature", className)}>
      <span>{children}</span>
      {value !== undefined ? <strong>{value}</strong> : null}
    </li>
  );
}

export function PricingFooter({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return <div {...rest} className={cx("hm-pricing-footer", className)} />;
}
